() => {
  const ids = ['email','street_address','zip_code','city','state','country','credit_card_number','credit_card_expiration_month','credit_card_expiration_year','credit_card_cvv'];
  const result = {};
  for (const id of ids) {
    const el = document.getElementById(id);
    if (el) {
      result[id] = { tag: el.tagName, type: el.type, required: el.required, pattern: el.pattern, min: el.min, max: el.max, minLength: el.minLength, maxLength: el.maxLength };
    } else {
      result[id] = 'NOT FOUND by id';
    }
  }
  // also dump all input/select testids and names
  const all = Array.from(document.querySelectorAll('input,select')).map(e => ({id: e.id, name: e.name, type: e.type, testid: e.getAttribute('data-testid'), required: e.required, pattern: e.pattern}));
  return { result, all };
}

() => {
  const cartImg = document.querySelector('img[alt="Cart icon"]');
  const cartAnchor = cartImg ? cartImg.closest('a') : null;
  const cartWrapper = cartImg ? cartImg.parentElement.outerHTML.slice(0,300) : null;
  const logo = document.querySelector('nav a');
  const currencySelect = document.querySelector('select[name="currency_code"]');
  return {
    cartAnchorHref: cartAnchor ? cartAnchor.getAttribute('href') : null,
    cartWrapperHTML: cartWrapper,
    logoHref: logo ? logo.getAttribute('href') : null,
    currencySelectExists: !!currencySelect,
    currencySelectId: currencySelect ? currencySelect.id : null,
  };
}

