() => {
  const items = document.querySelectorAll('[data-cy="product-price"]');
  // find common ancestor pattern - look for cart item rows
  const rows = document.querySelectorAll('a[href^="/product/"]');
  return Array.from(rows).map(a => {
    const row = a.closest('div')?.parentElement;
    return {
      href: a.getAttribute('href'),
      rowClass: row ? row.className : null,
      rowHTML: row ? row.outerHTML.slice(0, 500) : null,
    };
  });
}

